-- Skolenza Platform/Host access catalogue bootstrap.
-- Derived from the AxionPro canonical Host seed and converted to Institution/Campus vocabulary.
-- Run after 01-host-admin-bootstrap.sql.
BEGIN;
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM skolenza."HostRole" WHERE "Id"=1 AND "Name"='Host-Super-Admin' AND "IsActive"=TRUE AND "IsSoftDeleted"=FALSE) THEN RAISE EXCEPTION 'Run 01-host-admin-bootstrap.sql first.'; END IF;
 IF EXISTS (SELECT 1 FROM skolenza."Module") OR EXISTS (SELECT 1 FROM skolenza."Operation") OR EXISTS (SELECT 1 FROM skolenza."ModuleOperationMapping") OR EXISTS (SELECT 1 FROM skolenza."HostRoleModuleAndPermission") THEN RAISE EXCEPTION 'Host access catalogue bootstrap requires empty catalogue tables.'; END IF;
END $$;






-- Common menu is available to every authenticated principal and therefore has
-- no HostRoleModuleAndPermission rows. Its operation mappings are retained so
-- Navigation/my-menu can return the same stable tree as the source product.


SELECT setval(pg_get_serial_sequence('skolenza."Module"','Id'),(SELECT MAX("Id") FROM skolenza."Module"),TRUE);
SELECT setval(pg_get_serial_sequence('skolenza."ModuleOperationMapping"','Id'),(SELECT MAX("Id") FROM skolenza."ModuleOperationMapping"),TRUE);
SELECT setval(pg_get_serial_sequence('skolenza."HostRoleModuleAndPermission"','Id'),(SELECT MAX("Id") FROM skolenza."HostRoleModuleAndPermission"),TRUE);
DO $$ DECLARE a integer;b integer;c integer;d integer; BEGIN
 SELECT count(*) INTO a FROM skolenza."Module" WHERE "ModuleScope" IN (2,3) AND "IsActive"=TRUE;
 SELECT count(*) INTO b FROM skolenza."Operation" WHERE "IsActive"=TRUE;
 SELECT count(*) INTO c FROM skolenza."ModuleOperationMapping" WHERE "IsActive"=TRUE;
 SELECT count(*) INTO d FROM skolenza."HostRoleModuleAndPermission" WHERE "HostRoleId"=1 AND "IsActive"=TRUE AND "IsSoftDeleted"=FALSE;
 IF a<>44 OR b<>12 OR c<>120 OR d<>110 THEN RAISE EXCEPTION 'Reconciliation failed: modules %, operations %, mappings %, grants %',a,b,c,d; END IF;
END $$;
COMMIT;
